if not _items:
    raise ValueError("The CV content workflow returned no data.")

result = dict(_items[0].get("json", {}))
cv_json = result.get("cv_json")

if not isinstance(cv_json, dict):
    raise ValueError("Expected the CV content workflow to return a 'cv_json' object.")

return [
    {
        "json": {
            **result,
            "document_type": "cv",
            "document_data": cv_json,
        },
        "pairedItem": {"item": 0},
    }
]

if len(_items) < 2:
    raise ValueError("Expected two Cloudinary upload items.")

uploads = [item.get("json", {}) for item in _items]

tex_upload = next(
    (
        item
        for item in uploads
        if str(item.get("public_id", "")).endswith(".tex")
    ),
    None,
)

pdf_upload = next(
    (
        item
        for item in uploads
        if str(item.get("format", "")).lower() == "pdf"
        or str(item.get("public_id", "")).endswith(".pdf")
        or "/image/upload/" in str(item.get("secure_url", ""))
    ),
    None,
)

if not isinstance(tex_upload, dict):
    raise ValueError("Could not identify the TEX upload result.")

if not isinstance(pdf_upload, dict):
    raise ValueError("Could not identify the PDF upload result.")

tex_url = tex_upload.get("secure_url") or tex_upload.get("url")
pdf_url = pdf_upload.get("secure_url") or pdf_upload.get("url")

if not tex_url or not pdf_url:
    raise ValueError("Cloudinary did not return both TEX and PDF URLs.")

combined_public_id = " ".join(
    str(item.get("public_id", "")) for item in uploads
).lower()

document_type = (
    "cover_letter"
    if "cover-letter" in combined_public_id
    else "cv"
)

return [
    {
        "json": {
            "document_type": document_type,
            "tex_url": tex_url,
            "pdf_url": pdf_url,
            "tex_public_id": tex_upload.get("public_id"),
            "pdf_public_id": pdf_upload.get("public_id"),
        }
    }
]

if not _items:
    raise ValueError("The cover letter content workflow returned no data.")

result = dict(_items[0].get("json", {}))
cover_letter_json = result.get("cover_letter_json")

if not isinstance(cover_letter_json, dict):
    raise ValueError(
        "Expected the cover letter content workflow to return a 'cover_letter_json' object."
    )

return [
    {
        "json": {
            **result,
            "document_type": "cover-letter",
            "document_data": cover_letter_json,
        },
        "pairedItem": {"item": 0},
    }
]
